import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static final long INV2 = 499122177L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long l = sc.nextLong();
        long r = sc.nextLong();
        sc.close();

        long d = r - l + 1;
        long nm = n * m;
        long diff = d & 1L;

        long ans = (modPow(d, nm) + modPow(diff, nm)) % MOD;
        ans = ans * INV2 % MOD;
        if (nm % 2 == 1) {
            ans = modPow(d, nm);
        }
        System.out.println(ans);
    }

    static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}
